CREATE TABLE IF NOT EXISTS martyrs (
    id           VARCHAR(64) PRIMARY KEY,
    name         VARCHAR(200) NOT NULL,
    martyrdom    TEXT NOT NULL,
    born         VARCHAR(120) NOT NULL DEFAULT '',
    martyred_on  VARCHAR(120) NOT NULL DEFAULT '',
    place        VARCHAR(200) NOT NULL DEFAULT '',
    will         TEXT NOT NULL DEFAULT '',
    photo        TEXT NOT NULL DEFAULT '',
    sort_order   INT NOT NULL DEFAULT 0,
    is_active    BOOLEAN NOT NULL DEFAULT true,
    created_at   TIMESTAMP NOT NULL DEFAULT NOW(),
    updated_at   TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_martyrs_active_sort ON martyrs (is_active, sort_order);

