INSERT INTO martyrs (id, name, martyrdom, born, martyred_on, place, will, photo, sort_order) VALUES
    ('shahid-01', 'سردار سپهبد شهید قاسم سلیمانی', 'فرمانده نیروی قدس سپاه پاسداران. بامداد جمعه ۱۳ دی ۱۳۹۸ هنگام خروج از فرودگاه بین‌المللی بغداد، کاروان خودروهای او هدف حملهٔ پهپادی ارتش آمریکا قرار گرفت و به همراه ابومهدی المهندس و جمعی از همراهانشان به شهادت رسید. این ترور به دستور مستقیم رئیس‌جمهور وقت آمریکا انجام شد.', '۲۰ اسفند ۱۳۳۵ — رابر، کرمان', '۱۳ دی ۱۳۹۸', 'فرودگاه بین‌المللی بغداد، عراق', '', 'http://localhost:8090/uploads/martyrs/shahid-01.webp', 1),
    ('shahid-02', 'شهید ابومهدی المهندس', 'نایب‌رئیس سازمان حشد الشعبی عراق. در همان حملهٔ پهپادی آمریکا در نزدیکی فرودگاه بغداد، هنگام استقبال از سردار سلیمانی، در بامداد ۱۳ دی ۱۳۹۸ به شهادت رسید.', '۱۹۵۴ میلادی — بصره، عراق', '۱۳ دی ۱۳۹۸', 'فرودگاه بین‌المللی بغداد، عراق', '', 'http://localhost:8090/uploads/martyrs/shahid-02.webp', 2),
    ('shahid-03', 'سرتیپ خلبان شهید محمدباقر طاهرپور', 'فرمانده یگان پهپادی نیروی هوافضای سپاه. بامداد جمعه ۲۳ خرداد ۱۴۰۴ در حملهٔ رژیم صهیونیستی به مرکز فرماندهی نیروی هوافضای سپاه، همراه سردار امیرعلی حاجی‌زاده و جمعی دیگر از فرماندهان هوافضا به شهادت رسید.', '', '۲۳ خرداد ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-03.webp', 3),
    ('shahid-04', 'دکتر شهید محمدمهدی تهرانچی', 'فیزیکدان و رئیس دانشگاه آزاد اسلامی. بامداد ۲۳ خرداد ۱۴۰۴ در حملهٔ هوایی رژیم صهیونیستی به محل سکونتش در تهران، همراه با شماری دیگر از دانشمندان هسته‌ای کشور به شهادت رسید.', '', '۲۳ خرداد ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-04.webp', 4),
    ('shahid-05', 'سرتیپ پاسدار شهید حسن طهرانی مقدم', 'بنیان‌گذار و معمار صنعت موشکی ایران، معروف به «پدر صنعت موشکی». روز ۲۱ آبان ۱۳۹۰ در جریان یک انفجار در پایگاه شهید مدرس در منطقهٔ بیدگنه ملارد، همراه ۱۶ تن از همکارانش به شهادت رسید.', '', '۲۱ آبان ۱۳۹۰', 'پایگاه شهید مدرس، بیدگنه ملارد، استان تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-05.webp', 5),
    ('shahid-06', 'دریابان شهید علیرضا تنگسیری', 'فرمانده نیروی دریایی سپاه پاسداران از سال ۱۳۹۷. در جریان جنگ ۴۰ روزهٔ آمریکا و اسرائیل با ایران، هنگام ساماندهی و تقویت سپر دفاعی جزایر و سواحل خلیج فارس در حملهٔ دشمن به بندرعباس به‌شدت مجروح شد و بر اثر شدت جراحات به شهادت رسید. بیانیهٔ رسمی سپاه در ۱۰ فروردین ۱۴۰۵ منتشر شد.', '۵ شهریور ۱۳۴۲ — تنگستان، بوشهر', 'فروردین ۱۴۰۵ (بیانیهٔ سپاه: ۱۰ فروردین ۱۴۰۵)', 'بندرعباس، هرمزگان', '', 'http://localhost:8090/uploads/martyrs/shahid-06.webp', 6),
    ('shahid-07', 'سرلشکر پاسدار شهید محمدسعید ایزدی (حاج رمضان)', 'فرمانده قرارگاه فلسطین نیروی قدس سپاه پاسداران و از چهره‌های کلیدی پشتیبانی از مقاومت فلسطین طی بیش از سه دهه. بامداد ۳۱ خرداد ۱۴۰۴ در حملهٔ هوایی رژیم صهیونیستی به آپارتمان مسکونی‌اش در محلهٔ سالاریهٔ قم، همراه همسرش به شهادت رسید. نیروی قدس شهادت او را در اطلاعیه‌ای در یکم تیرماه اعلام کرد.', '', '۳۱ خرداد ۱۴۰۴ (اعلام رسمی: ۱ تیر ۱۴۰۴)', 'محلهٔ سالاریه، قم', '', 'http://localhost:8090/uploads/martyrs/shahid-07.webp', 7),
    ('shahid-08', 'سرلشکر پاسدار شهید امیرعلی حاجی‌زاده', 'فرمانده نیروی هوافضای سپاه پاسداران. بامداد جمعه ۲۳ خرداد ۱۴۰۴ در حملهٔ رژیم صهیونیستی به مرکز فرماندهی نیروی هوافضا، همراه هشت تن از فرماندهان ارشد این نیرو به شهادت رسید.', '', '۲۳ خرداد ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-08.webp', 8),
    ('shahid-09', 'سردار شهید داوود شیخیان', 'از فرماندهان ارشد نیروی هوافضای سپاه پاسداران. بامداد جمعه ۲۳ خرداد ۱۴۰۴ در حملهٔ رژیم صهیونیستی به مرکز فرماندهی هوافضا، همراه سردار حاجی‌زاده و دیگر همرزمانش به شهادت رسید.', '', '۲۳ خرداد ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-09.webp', 9),
    ('shahid-10', 'سرلشکر پاسدار شهید غلامعلی رشید', 'فرمانده قرارگاه مرکزی خاتم‌الانبیا(ص). بامداد ۲۳ خرداد ۱۴۰۴ در حملهٔ موشکی رژیم صهیونیستی به تهران، همراه پسرش به شهادت رسید.', '', '۲۳ خرداد ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-10.webp', 10),
    ('shahid-11', 'آیت‌الله شهید سید ابراهیم رئیسی', 'هشتمین رئیس‌جمهور جمهوری اسلامی ایران. در روز ۳۰ اردیبهشت ۱۴۰۳ در بازگشت از مراسم افتتاح سد قیز قلعه‌سی در مرز ایران و جمهوری آذربایجان، بالگرد حامل او در ارتفاعات مه‌آلود منطقهٔ ورزقان آذربایجان شرقی سقوط کرد و به همراه وزیر امور خارجه حسین امیرعبداللهیان و دیگر همراهان به شهادت رسید.', '', '۳۰ اردیبهشت ۱۴۰۳', 'ارتفاعات ورزقان، آذربایجان شرقی', '', 'http://localhost:8090/uploads/martyrs/shahid-11.webp', 11),
    ('shahid-12', 'شهیده زهرا محمدی گلپایگانی', 'کودک ۱۴ماهه و نوهٔ دختری رهبر شهید انقلاب. در روز ۹ اسفند ۱۴۰۴، نخستین روز حملات مشترک آمریکا و اسرائیل، در حمله به مجموعهٔ بیت رهبری همراه مادرش و پدربزرگش به شهادت رسید. تابوت کوچک او در مراسم تشییع، به یکی از شاخص‌ترین تصاویر آن روزها بدل شد.', '۲۸ آذر ۱۴۰۳', '۹ اسفند ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-12.webp', 12),
    ('shahid-13', 'سرلشکر پاسدار شهید حسین سلامی', 'فرمانده کل سپاه پاسداران انقلاب اسلامی. بامداد جمعه ۲۳ خرداد ۱۴۰۴ در نخستین موج حملات رژیم صهیونیستی به ستاد فرماندهی سپاه در تهران به شهادت رسید. شهادت او در همان ساعات نخست به‌طور رسمی تأیید شد.', '', '۲۳ خرداد ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-13.webp', 13),
    ('shahid-14', 'سردار شهید مرتضی طیب‌مسعود', 'از فرماندهان گمنام و ارشد نیروی هوافضای سپاه و از همرزمان دیرین سردار حاجی‌زاده و سردار سلیمانی که سابقهٔ حضور و مجروحیت در سوریه را نیز داشت. بامداد ۲۳ خرداد ۱۴۰۴ در حملهٔ رژیم صهیونیستی به مرکز فرماندهی هوافضا به شهادت رسید. اهل رزن همدان بود.', '', '۲۳ خرداد ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-14.webp', 14),
    ('shahid-15', 'دکتر شهید محسن فخری‌زاده', 'دانشمند برجستهٔ هسته‌ای و دفاعی و از چهره‌های کلیدی صنعت هسته‌ای کشور. روز ۷ آذر ۱۳۹۹ در جادهٔ آبسرد دماوند در یک عملیات ترور با سلاح خودکار کنترل از راه دور هدف قرار گرفت و به شهادت رسید.', '', '۷ آذر ۱۳۹۹', 'آبسرد، دماوند، استان تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-15.webp', 15),
    ('shahid-16', 'دکتر شهید فریدون عباسی دوانی', 'دانشمند هسته‌ای، رئیس اسبق سازمان انرژی اتمی ایران و نمایندهٔ مجلس شورای اسلامی. پیش‌تر در سال ۱۳۸۹ از یک ترور جان سالم به در برده بود. بامداد ۲۳ خرداد ۱۴۰۴ در حملهٔ هوایی رژیم صهیونیستی به محل سکونتش در تهران به شهادت رسید.', '', '۲۳ خرداد ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-16.webp', 16),
    ('shahid-17', 'دکتر شهید سید امیرحسین فقهی', 'معاون سازمان انرژی اتمی، رئیس پژوهشگاه علوم و فنون هسته‌ای و عضو هیئت علمی دانشکدهٔ مهندسی هسته‌ای دانشگاه شهید بهشتی؛ از چهره‌های شاخص حوزهٔ رادیوداروها. بامداد ۲۳ خرداد ۱۴۰۴ خانهٔ او در حملهٔ رژیم صهیونیستی هدف قرار گرفت و به شهادت رسید.', 'شهریور ۱۳۵۷ — شیراز', '۲۳ خرداد ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-17.webp', 17),
    ('shahid-18', 'سرلشکر پاسدار شهید محمدحسن محققی (حسن محقق)', 'جانشین سازمان اطلاعات سپاه پاسداران، از فرماندهان دوران دفاع مقدس و جانباز جنگ تحمیلی. روز ۲۵ خرداد ۱۴۰۴ در حملهٔ موشکی رژیم صهیونیستی به ساختمان مرکزی سازمان اطلاعات سپاه به شهادت رسید.', '', '۲۵ خرداد ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-18.webp', 18),
    ('shahid-19', 'سردار شهید محمود باقری', 'فرمانده نیروی موشکی هوافضای سپاه پاسداران که از سال ۱۳۸۸ با حکم فرماندهی کل قوا به این سمت منصوب شده بود. بامداد ۲۳ خرداد ۱۴۰۴ در حملهٔ رژیم صهیونیستی به مرکز فرماندهی نیروی هوافضا، همراه سردار حاجی‌زاده به شهادت رسید.', '', '۲۳ خرداد ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-19.webp', 19),
    ('shahid-20', 'شهید عماد مغنیه (حاج رضوان)', 'فرمانده نظامی حزب‌الله لبنان. در ۲۳ بهمن ۱۳۸۶ (۱۲ فوریهٔ ۲۰۰۸) در محلهٔ کفرسوسهٔ دمشق، با انفجار خودروی بمب‌گذاری‌شده ترور شد.', '', '۲۳ بهمن ۱۳۸۶', 'کفرسوسه، دمشق، سوریه', '', 'http://localhost:8090/uploads/martyrs/shahid-20.webp', 20),
    ('shahid-21', 'امیر سپهبد شهید سید عبدالرحیم موسوی', 'چهارمین رئیس ستاد کل نیروهای مسلح که پس از شهادت سرلشکر محمد باقری در خرداد ۱۴۰۴ به این سمت منصوب شد و پیش از آن از سال ۱۳۹۶ فرمانده کل ارتش بود. صبح ۹ اسفند ۱۴۰۴، در نخستین موج حملات مشترک آمریکا و اسرائیل، هنگام برگزاری جلسهٔ شورای دفاع، همراه سپهبد محمد پاکپور، دریاسالار علی شمخانی و سرلشکر عزیز نصیرزاده به شهادت رسید.', '۱۳۳۹ — قم', '۹ اسفند ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-21.webp', 21),
    ('shahid-22', 'دکتر شهید عبدالحمید مینوچهر', 'رئیس دانشکدهٔ مهندسی هسته‌ای دانشگاه شهید بهشتی و متخصص فیزیک راکتور، شبیه‌سازی هسته‌ای و طراحی سوخت‌های پیشرفته. بامداد ۲۳ خرداد ۱۴۰۴ در حملهٔ رژیم صهیونیستی به محل سکونتش در تهران به شهادت رسید.', '', '۲۳ خرداد ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-22.webp', 22),
    ('shahid-23', 'شهید سید حسن نصرالله', 'دبیرکل حزب‌الله لبنان از سال ۱۹۹۲. عصر ۶ مهر ۱۴۰۳ (۲۷ سپتامبر ۲۰۲۴) در بمباران سنگین جنگنده‌های رژیم صهیونیستی بر مقر فرماندهی حزب‌الله در منطقهٔ ضاحیهٔ جنوبی بیروت به شهادت رسید.', '', '۶ مهر ۱۴۰۳', 'ضاحیهٔ جنوبی بیروت، لبنان', '', 'http://localhost:8090/uploads/martyrs/shahid-23.webp', 23),
    ('shahid-24', 'دکتر شهید مصطفی چمران', 'نخستین وزیر دفاع جمهوری اسلامی، نمایندهٔ مجلس و فرماندهٔ ستاد جنگ‌های نامنظم. روز ۳۱ خرداد ۱۳۶۰ در جبههٔ دهلاویه در نزدیکی سوسنگرد بر اثر اصابت ترکش خمپاره به شهادت رسید.', '', '۳۱ خرداد ۱۳۶۰', 'دهلاویه، سوسنگرد، خوزستان', '', 'http://localhost:8090/uploads/martyrs/shahid-24.webp', 24),
    ('shahid-25', 'شهید یحیی السنوار', 'رئیس دفتر سیاسی جنبش حماس و از فرماندهان اصلی مقاومت فلسطین. روز ۲۵ مهر ۱۴۰۳ (۱۶ اکتبر ۲۰۲۴) در منطقهٔ تل‌السلطان رفح در جنوب نوار غزه، در جریان درگیری میدانی با نیروهای اشغالگر به شهادت رسید.', '', '۲۵ مهر ۱۴۰۳', 'تل‌السلطان، رفح، نوار غزه', '', 'http://localhost:8090/uploads/martyrs/shahid-25.webp', 25),
    ('shahid-26', 'سردار سپهبد شهید محمد پاکپور', 'هشتمین فرمانده کل سپاه پاسداران انقلاب اسلامی که پس از شهادت سردار حسین سلامی در ۲۳ خرداد ۱۴۰۴ به این سمت منصوب شد و پیش از آن سال‌ها فرماندهی نیروی زمینی سپاه را بر عهده داشت. صبح ۹ اسفند ۱۴۰۴ در نخستین موج حملات مشترک آمریکا و اسرائیل، در جریان جلسهٔ شورای دفاع در مجموعهٔ دفتر رهبری، همراه سپهبد سید عبدالرحیم موسوی، دریاسالار علی شمخانی و سرلشکر عزیز نصیرزاده به شهادت رسید. پیکر او در اراک تشییع شد.', '۱۳۴۰ — اراک، مرکزی', '۹ اسفند ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-26.webp', 26),
    ('shahid-27', 'امیر سرلشکر شهید عزیز نصیرزاده', 'وزیر دفاع و پشتیبانی نیروهای مسلح و از فرماندهان پیشین نیروی هوایی ارتش جمهوری اسلامی ایران. صبح ۹ اسفند ۱۴۰۴ در حین برگزاری جلسهٔ شورای دفاع، در حملهٔ مشترک آمریکا و اسرائیل به تهران، همراه دیگر اعضای حاضر در جلسه به شهادت رسید.', '', '۹ اسفند ۱۴۰۴', 'تهران', '', 'http://localhost:8090/uploads/martyrs/shahid-27.webp', 27)
